[metadata] {"type": "create", "filePath": "/app/output/malaria-poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Malaria: A Preventable Killer — Global Progress and the Road Ahead</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=DM+Sans:wght@400;500;700&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    width: 594mm;
    height: 841mm;
    background: #0f172a;
    color: #e2e8f0;
    font-family: 'Inter', 'DM Sans', sans-serif;
    overflow: hidden;
  }

  .poster {
    width: 100%;
    height: 100%;
    padding: 48px 56px;
    display: flex;
    flex-direction: column;
    gap: 0;
    position: relative;
    background:
      radial-gradient(ellipse 80% 40% at 50% 0%, rgba(30,58,138,0.35) 0%, transparent 70%),
      radial-gradient(ellipse 60% 30% at 80% 100%, rgba(120,53,15,0.2) 0%, transparent 70%),
      #0f172a;
  }

  /* ===== HEADER ===== */
  .header {
    text-align: center;
    padding-bottom: 36px;
    border-bottom: 1px solid rgba(148,163,184,0.15);
    flex-shrink: 0;
  }
  .header .mosquito-icon {
    font-size: 36px;
    color: #f59e0b;
    letter-spacing: 12px;
    margin-bottom: 8px;
  }
  .header h1 {
    font-size: 52px;
    font-weight: 900;
    line-height: 1.1;
    letter-spacing: -1px;
    background: linear-gradient(135deg, #ffffff 0%, #cbd5e1 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }
  .header h1 span.accent {
    background: linear-gradient(135deg, #f59e0b 0%, #ef4444 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }
  .header .subtitle {
    font-size: 20px;
    color: #94a3b8;
    margin-top: 12px;
    font-weight: 400;
    max-width: 85%;
    margin-left: auto;
    margin-right: auto;
    line-height: 1.5;
  }

  /* ===== HERO STAT ===== */
  .hero-stat {
    text-align: center;
    padding: 44px 40px;
    margin: 32px 0;
    background: linear-gradient(135deg, rgba(220,38,38,0.12) 0%, rgba(245,158,11,0.08) 100%);
    border: 2px solid rgba(239,68,68,0.3);
    border-radius: 20px;
    position: relative;
    flex-shrink: 0;
  }
  .hero-stat::before {
    content: '';
    position: absolute;
    inset: -2px;
    border-radius: 22px;
    background: linear-gradient(135deg, rgba(239,68,68,0.4), rgba(245,158,11,0.4));
    z-index: -1;
    filter: blur(20px);
    opacity: 0.5;
  }
  .hero-stat .big-number {
    font-size: 128px;
    font-weight: 900;
    line-height: 1;
    background: linear-gradient(135deg, #ef4444 0%, #f59e0b 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    letter-spacing: -3px;
  }
  .hero-stat .big-label {
    font-size: 38px;
    font-weight: 700;
    color: #fbbf24;
    margin-top: 4px;
    letter-spacing: 1px;
  }
  .hero-stat .big-context {
    font-size: 22px;
    color: #94a3b8;
    margin-top: 12px;
    line-height: 1.4;
  }
  .hero-stat .big-context strong {
    color: #fbbf24;
  }

  /* ===== MAIN GRID ===== */
  .main-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto auto;
    gap: 28px;
    flex: 1;
    min-height: 0;
  }

  .section {
    background: rgba(30,41,59,0.6);
    border: 1px solid rgba(148,163,184,0.1);
    border-radius: 16px;
    padding: 32px;
    display: flex;
    flex-direction: column;
  }
  .section-label {
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 3px;
    color: #64748b;
    margin-bottom: 8px;
  }
  .section h2 {
    font-size: 26px;
    font-weight: 800;
    color: #f8fafc;
    margin-bottom: 16px;
    line-height: 1.2;
  }
  .section p {
    font-size: 15px;
    line-height: 1.6;
    color: #94a3b8;
    margin-bottom: 16px;
  }

  /* --- Historical Progress Section --- */
  .progress-section {
    grid-column: 1;
    grid-row: 1;
  }
  .map-comparison {
    display: flex;
    align-items: center;
    gap: 20px;
    margin-top: auto;
  }
  .map-box {
    flex: 1;
    text-align: center;
  }
  .map-box .map-visual {
    width: 100%;
    height: 120px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
  }
  .map-box .era-label {
    font-size: 13px;
    color: #64748b;
    margin-top: 8px;
    font-weight: 500;
  }
  .map-box .percentage {
    font-size: 48px;
    font-weight: 900;
    line-height: 1;
  }
  .map-box .pct-label {
    font-size: 14px;
    font-weight: 500;
    margin-top: 2px;
  }
  .map-arrow {
    font-size: 32px;
    color: #22c55e;
    flex-shrink: 0;
  }

  /* --- Death Trends Chart Section --- */
  .trends-section {
    grid-column: 2;
    grid-row: 1 / 3;
  }
  .chart-container {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
  }
  .chart-area {
    flex: 1;
    position: relative;
    min-height: 280px;
  }
  .chart-svg {
    width: 100%;
    height: 100%;
  }
  .chart-legend {
    display: flex;
    gap: 20px;
    margin-top: 12px;
    flex-wrap: wrap;
  }
  .legend-item {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 12px;
    color: #94a3b8;
  }
  .legend-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    flex-shrink: 0;
  }
  .chart-annotations {
    display: flex;
    gap: 12px;
    margin-top: 12px;
    flex-wrap: wrap;
  }
  .annotation-tag {
    font-size: 11px;
    padding: 4px 10px;
    border-radius: 6px;
    font-weight: 600;
  }

  /* --- Interventions Section --- */
  .interventions-section {
    grid-column: 1;
    grid-row: 2;
  }
  .intervention-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 16px;
    margin-top: auto;
  }
  .intervention-item {
    display: flex;
    gap: 16px;
    align-items: flex-start;
  }
  .intervention-icon {
    width: 44px;
    height: 44px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 22px;
    flex-shrink: 0;
  }
  .intervention-text h3 {
    font-size: 16px;
    font-weight: 700;
    color: #f1f5f9;
    margin-bottom: 2px;
  }
  .intervention-text p {
    font-size: 13px;
    color: #94a3b8;
    margin: 0;
    line-height: 1.4;
  }

  /* ===== FOOTER ===== */
  .footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 24px;
    margin-top: 28px;
    border-top: 1px solid rgba(148,163,184,0.1);
    flex-shrink: 0;
  }
  .footer .source {
    font-size: 12px;
    color: #475569;
    line-height: 1.6;
  }
  .footer .branding {
    font-size: 12px;
    color: #475569;
    text-align: right;
  }

  /* Metric pills */
  .metric-row {
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
    margin-top: 12px;
  }
  .metric-pill {
    background: rgba(15,23,42,0.5);
    border: 1px solid rgba(148,163,184,0.1);
    border-radius: 10px;
    padding: 12px 16px;
    flex: 1;
    min-width: 140px;
  }
  .metric-pill .mp-value {
    font-size: 22px;
    font-weight: 800;
    color: #f8fafc;
  }
  .metric-pill .mp-label {
    font-size: 11px;
    color: #64748b;
    margin-top: 2px;
    font-weight: 500;
  }

  /* Bar chart styling for burden */
  .burden-bars {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 12px;
  }
  .burden-bar {
    display: flex;
    align-items: center;
    gap: 10px;
  }
  .burden-bar .bar-label {
    font-size: 12px;
    color: #94a3b8;
    width: 100px;
    text-align: right;
    flex-shrink: 0;
  }
  .burden-bar .bar-track {
    flex: 1;
    height: 18px;
    background: rgba(15,23,42,0.4);
    border-radius: 4px;
    overflow: hidden;
  }
  .burden-bar .bar-fill {
    height: 100%;
    border-radius: 4px;
  }
  .burden-bar .bar-value {
    font-size: 12px;
    font-weight: 700;
    width: 50px;
    flex-shrink: 0;
  }
</style>
</head>
