<div class="poster">

  <!-- HEADER -->
  <div class="header">
    <div class="mosquito-icon">&#9676; &#9676; &#9676;</div>
    <h1>Malaria: <span class="accent">A Preventable Killer</span></h1>
    <p class="subtitle">Over half a million people still die from malaria each year, most of them children &mdash; yet humanity has made remarkable progress eliminating the disease from half the world.</p>
  </div>

  <!-- HERO STAT: 1,320 children every day -->
  <div class="hero-stat">
    <div class="big-number">1,320</div>
    <div class="big-label">CHILDREN DIE EVERY DAY</div>
    <div class="big-context">from a disease we already know how to <strong>prevent and treat</strong>.<br>That is one child every <strong>65 seconds</strong>.</div>
  </div>

  <!-- MAIN CONTENT GRID -->
  <div class="main-grid">

    <!-- SECTION 1: Historical Progress -->
    <div class="section progress-section">
      <div class="section-label">Historical Progress</div>
      <h2>From Half the World to a Quarter</h2>
      <p>Malaria was once endemic across roughly 50% of the world's land surface &mdash; including Europe and North America. By 2002, the area at risk shrank to ~27%. Public health measures, land use changes, and economic development drove this dramatic retreat.</p>

      <div class="map-comparison">
        <div class="map-box">
          <div class="map-visual" style="background: linear-gradient(135deg, rgba(239,68,68,0.2), rgba(239,68,68,0.05));">
            <div>
              <div class="percentage" style="color: #ef4444;">~50%</div>
              <div class="pct-label" style="color: #fca5a5;">of land surface</div>
            </div>
          </div>
          <div class="era-label">~1900</div>
        </div>
        <div class="map-arrow">&#10140;</div>
        <div class="map-box">
          <div class="map-visual" style="background: linear-gradient(135deg, rgba(34,197,94,0.2), rgba(34,197,94,0.05));">
            <div>
              <div class="percentage" style="color: #22c55e;">~27%</div>
              <div class="pct-label" style="color: #86efac;">of land surface</div>
            </div>
          </div>
          <div class="era-label">2002</div>
        </div>
      </div>

      <div class="metric-row" style="margin-top:16px;">
        <div class="metric-pill">
          <div class="mp-value" style="color:#22c55e;">46%</div>
          <div class="mp-label">Reduction in endemic area</div>
        </div>
        <div class="metric-pill">
          <div class="mp-value">3</div>
          <div class="mp-label">Key drivers of elimination</div>
        </div>
      </div>
    </div>

    <!-- SECTION 2: Death Trends Chart (tall, spans 2 rows) -->
    <div class="section trends-section">
      <div class="section-label">Death Toll Trends</div>
      <h2>Malaria Deaths: 2000&ndash;2023</h2>
      <p style="margin-bottom:8px;">Global deaths fell sharply from 2000 to 2015, then progress stalled. COVID-19 disruptions in 2020 pushed deaths back up.</p>

      <div class="chart-container">
        <div class="chart-area">
          <svg class="chart-svg" viewBox="0 0 460 340" preserveAspectRatio="xMidYMid meet">
            <!-- Grid lines -->
            <line x1="50" y1="20" x2="50" y2="290" stroke="#1e293b" stroke-width="1"/>
            <line x1="50" y1="290" x2="445" y2="290" stroke="#334155" stroke-width="1"/>
            <line x1="50" y1="236" x2="445" y2="236" stroke="#1e293b" stroke-width="0.5" stroke-dasharray="4"/>
            <line x1="50" y1="182" x2="445" y2="182" stroke="#1e293b" stroke-width="0.5" stroke-dasharray="4"/>
            <line x1="50" y1="128" x2="445" y2="128" stroke="#1e293b" stroke-width="0.5" stroke-dasharray="4"/>
            <line x1="50" y1="74" x2="445" y2="74" stroke="#1e293b" stroke-width="0.5" stroke-dasharray="4"/>
            <line x1="50" y1="20" x2="445" y2="20" stroke="#1e293b" stroke-width="0.5" stroke-dasharray="4"/>

            <!-- Y-axis labels -->
            <text x="45" y="293" text-anchor="end" fill="#64748b" font-size="10" font-family="Inter">0</text>
            <text x="45" y="239" text-anchor="end" fill="#64748b" font-size="10" font-family="Inter">200K</text>
            <text x="45" y="185" text-anchor="end" fill="#64748b" font-size="10" font-family="Inter">400K</text>
            <text x="45" y="131" text-anchor="end" fill="#64748b" font-size="10" font-family="Inter">600K</text>
            <text x="45" y="77" text-anchor="end" fill="#64748b" font-size="10" font-family="Inter">800K</text>
            <text x="45" y="23" text-anchor="end" fill="#64748b" font-size="10" font-family="Inter">1M</text>

            <!-- Y-axis title -->
            <text x="12" y="155" text-anchor="middle" fill="#64748b" font-size="10" font-family="Inter" transform="rotate(-90, 12, 155)">Estimated deaths</text>

            <!-- X-axis labels -->
            <text x="67" y="308" text-anchor="middle" fill="#64748b" font-size="10" font-family="Inter">2000</text>
            <text x="150" y="308" text-anchor="middle" fill="#64748b" font-size="10" font-family="Inter">2005</text>
            <text x="232" y="308" text-anchor="middle" fill="#64748b" font-size="10" font-family="Inter">2010</text>
            <text x="315" y="308" text-anchor="middle" fill="#64748b" font-size="10" font-family="Inter">2015</text>
            <text x="397" y="308" text-anchor="middle" fill="#64748b" font-size="10" font-family="Inter">2020</text>
            <text x="428" y="308" text-anchor="middle" fill="#64748b" font-size="10" font-family="Inter">'23</text>

            <!-- WHO estimate area fill -->
            <defs>
              <linearGradient id="whoGrad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stop-color="#3b82f6" stop-opacity="0.3"/>
                <stop offset="100%" stop-color="#3b82f6" stop-opacity="0.02"/>
              </linearGradient>
              <linearGradient id="ihmeGrad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stop-color="#f59e0b" stop-opacity="0.25"/>
                <stop offset="100%" stop-color="#f59e0b" stop-opacity="0.02"/>
              </linearGradient>
            </defs>

            <!-- IHME area -->
            <path d="M67,101 L83,95 L100,88 L117,82 L133,78 L150,74 L167,70 L183,66 L200,72 L216,80 L232,93 L249,107 L265,120 L282,131 L298,142 L315,152 L331,160 L348,166 L364,172 L380,176 L397,173 L397,290 L67,290 Z" fill="url(#ihmeGrad)"/>

            <!-- IHME line -->
            <polyline points="67,101 83,95 100,88 117,82 133,78 150,74 167,70 183,66 200,72 216,80 232,93 249,107 265,120 282,131 298,142 315,152 331,160 348,166 364,172 380,176 397,173" fill="none" stroke="#f59e0b" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>

            <!-- WHO area -->
            <path d="M67,128 L83,124 L100,119 L117,115 L133,112 L150,110 L167,116 L183,125 L200,136 L216,147 L232,154 L249,161 L265,167 L282,172 L298,178 L315,183 L331,186 L348,188 L364,190 L380,192 L397,179 L413,182 L428,185 L428,290 L67,290 Z" fill="url(#whoGrad)"/>

            <!-- WHO line -->
            <polyline points="67,128 83,124 100,119 117,115 133,112 150,110 167,116 183,125 200,136 216,147 232,154 249,161 265,167 282,172 298,178 315,183 331,186 348,188 364,190 380,192 397,179 413,182 428,185" fill="none" stroke="#3b82f6" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>

